LOCK_NAME = "skills-pack.lock.json"
IGNORED = {"__pycache__", ".pytest_cache", ".DS_Store"}  # local by-products, not part of the pack
NOTE_NAME = "VENDORED.md"


class Abort(Exception):
    pass


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 16), b""):
            h.update(chunk)
    return h.hexdigest()


def find_repo(arg: str | None) -> Path:
    root = Path(arg or os.getcwd()).resolve()
    if not (root / "backend" / "app").is_dir() or not (root / "desktop" / "src-tauri").is_dir():
        raise Abort(f"{root} is not the scalp-app repo root (backend/app and desktop/src-tauri expected). "
                    "cd to the repo root or pass --repo.")
    return root


def unpack_payload(dest: Path) -> dict:
    raw = base64.b64decode("".join(PAYLOAD_B64))
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise Abort("payload checksum mismatch — the script was altered or truncated; re-download it.")
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
        for m in tf.getmembers():
            name = Path(m.name)
            if name.is_absolute() or ".." in name.parts or not (m.isfile() or m.isdir()):
                raise Abort(f"unexpected payload entry {m.name!r}")
        kw = {"filter": "data"} if hasattr(tarfile, "data_filter") else {}
        tf.extractall(dest, **kw)
    lock = json.loads((dest / LOCK_NAME).read_text(encoding="utf-8"))
    if lock.get("fence") != FENCE:
        raise Abort("payload lock has the wrong fence")
    return lock


def check_payload(stage: Path, lock: dict) -> None:
    files = lock["files"]
    # 1. every file matches the lock, and nothing extra is present
    seen = set()
    for p in stage.rglob("*"):
        if p.is_file():
            rel = p.relative_to(stage).as_posix()
            if rel == LOCK_NAME:
                continue
            seen.add(rel)
            if rel not in files:
                raise Abort(f"payload file not in lock: {rel}")
            if sha256_file(p) != files[rel]:
                raise Abort(f"payload file changed: {rel}")
    missing = set(files) - seen
    if missing:
        raise Abort(f"payload files missing: {sorted(missing)[:5]}")
    # 2. py_compile gate on every Python file
    with tempfile.TemporaryDirectory() as tmp:
        for rel in files:
            if rel.endswith(".py"):
                try:
                    py_compile.compile(str(stage / rel), cfile=os.path.join(tmp, "x.pyc"), doraise=True)
                except py_compile.PyCompileError as e:
                    raise Abort(f"py_compile failed for {rel}: {e.msg}")
    # 3. each skill has SKILL.md with frontmatter name == folder and a description
    for s in SKILLS:
        md = stage / s / "SKILL.md"
        if not md.is_file():
            raise Abort(f"{s}: SKILL.md missing")
        text = md.read_text(encoding="utf-8")
        if not text.startswith("---\n") or "\n---" not in text[4:]:
            raise Abort(f"{s}: SKILL.md has no frontmatter")
        front = text[4:text.index("\n---", 4)]
        names = [ln.split(":", 1)[1].strip().strip('"') for ln in front.splitlines() if ln.startswith("name:")]
        if names != [s]:
            raise Abort(f"{s}: frontmatter name is {names}, expected {s!r}")
        if not any(ln.startswith("description:") for ln in front.splitlines()):
            raise Abort(f"{s}: frontmatter has no description")
        if not (stage / s / "LICENSE").is_file() and not (stage / s / "LICENSE.txt").is_file():
            raise Abort(f"{s}: licence file missing")


def git_dirty(repo: Path) -> list[str] | None:
    try:
        out = subprocess.run(["git", "status", "--porcelain", "--", ".claude/skills"], cwd=repo,
                             capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired):
        return None
    if out.returncode != 0:
        return None
    return [ln for ln in out.stdout.splitlines() if ln.strip()]


def preflight(repo: Path, allow_dirty: bool) -> Path:
    skills_dir = repo / ".claude" / "skills"
    note = skills_dir / NOTE_NAME
    if note.is_file() and FENCE in note.read_text(encoding="utf-8", errors="replace"):
        raise Abort(f"already applied ({FENCE} found in .claude/skills/{NOTE_NAME}). Nothing to do. "
                    "Use --verify to check it, --rollback to remove it.")
    clash = [s for s in SKILLS if (skills_dir / s).exists()]
    clash += [n for n in (NOTE_NAME, LOCK_NAME) if (skills_dir / n).exists()]
    if clash:
        raise Abort("these already exist in .claude/skills and would be overwritten: " + ", ".join(clash)
                    + ". Move them away first (nothing was changed).")
    dirty = git_dirty(repo)
    if dirty is None:
        print("  ! git status unavailable — skipping the uncommitted-changes check")
    elif dirty and not allow_dirty:
        raise Abort("uncommitted changes under .claude/skills (commit or stash first, or pass --allow-dirty):\n    "
                    + "\n    ".join(dirty[:10]))
    return skills_dir


def install(repo: Path, dry_run: bool, allow_dirty: bool) -> None:
    skills_dir = preflight(repo, allow_dirty)
    with tempfile.TemporaryDirectory(prefix="skills_pack_") as tmp:
        stage = Path(tmp) / "pack"
        stage.mkdir()
        lock = unpack_payload(stage)
        check_payload(stage, lock)
        print(f"  payload OK: {len(lock['files'])} files, {len(SKILLS)} skills, py_compile clean")
        if dry_run:
            print("  dry run — nothing written")
            return
        skills_dir.mkdir(parents=True, exist_ok=True)
        staging = skills_dir / f".staging-{FENCE}"
        if staging.exists():
            shutil.rmtree(staging)
        shutil.copytree(stage, staging)
        moved: list[Path] = []
        try:
            for name in SKILLS + [LOCK_NAME, NOTE_NAME]:  # VENDORED.md (the fence) lands last
                src, dst = staging / name, skills_dir / name
                os.replace(src, dst)
                moved.append(dst)
        except BaseException:
            for dst in reversed(moved):
                if dst.is_dir():
                    shutil.rmtree(dst, ignore_errors=True)
                else:
                    dst.unlink(missing_ok=True)
            raise
        finally:
            shutil.rmtree(staging, ignore_errors=True)
    bad = verify(repo, quiet=True)
    if bad:
        raise Abort("post-install verify failed: " + "; ".join(bad[:5]))
    smoke(skills_dir)
    print(f"  installed {len(SKILLS)} skills into .claude/skills ({FENCE})")
    print("  next: git add .claude/skills && git commit -m \"SKILLS_PACK_20261117: vendored skills\" && git push")


def smoke(skills_dir: Path) -> None:
    script = skills_dir / "backtest-expert" / "scripts" / "evaluate_backtest.py"
    with tempfile.TemporaryDirectory() as out:
        r = subprocess.run([sys.executable, "-I", str(script), "--total-trades", "150", "--win-rate", "62",
                            "--avg-win-pct", "1.8", "--avg-loss-pct", "1.2", "--max-drawdown-pct", "15",
                            "--years-tested", "8", "--num-parameters", "3", "--slippage-tested",
                            "--output-dir", out], capture_output=True, text=True, timeout=60)
        reports = list(Path(out).glob("backtest_eval_*.json"))
        if r.returncode != 0 or not reports:
            raise Abort(f"smoke test of backtest-expert failed (exit {r.returncode}): {r.stderr[-300:]}")
        decision = json.loads(reports[0].read_text(encoding="utf-8")).get("decision")
    print(f"  smoke: backtest-expert evaluate_backtest.py ran (decision {decision})")


def verify(repo: Path, quiet: bool = False) -> list[str]:
    skills_dir = repo / ".claude" / "skills"
    lock_path = skills_dir / LOCK_NAME
    if not lock_path.is_file():
        return [f"{LOCK_NAME} not found — pack not installed"]
    lock = json.loads(lock_path.read_text(encoding="utf-8"))
    bad = []
    for rel, digest in lock["files"].items():
        p = skills_dir / rel
        if not p.is_file():
            bad.append(f"missing {rel}")
        elif sha256_file(p) != digest:
            bad.append(f"changed {rel}")
    for s in SKILLS:
        d = skills_dir / s
        if d.is_dir():
            for p in d.rglob("*"):
                if p.is_file() and not (IGNORED & set(p.parts)):
                    rel = p.relative_to(skills_dir).as_posix()
                    if rel not in lock["files"]:
                        bad.append(f"extra {rel}")
    if not quiet:
        print("  verify: OK — all files match the lock" if not bad else "  verify: " + "\n    ".join(bad))
    return bad


def rollback(repo: Path, force: bool) -> None:
    skills_dir = repo / ".claude" / "skills"
    if not (skills_dir / LOCK_NAME).is_file():
        raise Abort("nothing to roll back (lock file not found)")
    bad = verify(repo, quiet=True)
    if bad and not force:
        raise Abort("installed files were changed since install — not removing them (use --force):\n    "
                    + "\n    ".join(bad[:10]))
    for s in SKILLS:
        shutil.rmtree(skills_dir / s, ignore_errors=True)
    for n in (LOCK_NAME, NOTE_NAME):
        (skills_dir / n).unlink(missing_ok=True)
    print(f"  rolled back {FENCE}: removed {len(SKILLS)} skills, {NOTE_NAME}, {LOCK_NAME}")


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--repo", help="repo root (default: current directory)")
    g = ap.add_mutually_exclusive_group()
    g.add_argument("--dry-run", action="store_true")
    g.add_argument("--verify", action="store_true")
    g.add_argument("--rollback", action="store_true")
    ap.add_argument("--allow-dirty", action="store_true", help="skip the uncommitted-changes check")
    ap.add_argument("--force", action="store_true", help="rollback even if files were changed")
    a = ap.parse_args(argv)
    print(f"{FENCE}")
    try:
        repo = find_repo(a.repo)
        if a.verify:
            return 1 if verify(repo) else 0
        if a.rollback:
            rollback(repo, a.force)
            return 0
        install(repo, a.dry_run, a.allow_dirty)
        return 0
    except Abort as e:
        print(f"  ABORT: {e}")
        return 2


if __name__ == "__main__":
    sys.exit(main())
